// Package store is the data access layer over PostgreSQL (D3):
//
//   - package q, generated by sqlc (`make generate`) from queries/*.sql,
//     holds the static queries: one file per table, each list query
//     joins what its page shows so that a page runs a bounded number of
//     queries (N2);
//   - this package adds transactions with retries (Store.InTx) and the
//     queries whose SQL depends on the filters (ListSubmissions), written
//     by hand with pgx.
//
// Conventions of the queries:
//
//   - Get… returns pgx.ErrNoRows when nothing matches; Update… returns the
//     updated row (pgx.ErrNoRows when the id does not exist); Delete…
//     returns the number of deleted rows.
//   - NOT NULL array columns are written through coalesce(…, '{}'): a nil
//     Go slice stores an empty array. In nullable array columns (the
//     participation IP list, the allowed languages of a task) nil is NULL
//     and means something else than an empty slice.
//   - Results written by workers are idempotent and the first result
//     wins: Set…Compilation, Set…Evaluation, SetSubmissionScore and
//     Create…Executable/CreateEvaluation… affect 0 rows when the result
//     is already there, so a job delivered twice stores nothing twice.
//     Failed attempts too: Set…Compilation and Set…Evaluation take the
//     job's attempt number (1 for the first job, the result's tries + 1
//     for a retry) and the tries become the highest attempt seen, so a
//     failure delivered twice counts once (and affects 0 rows the second
//     time: do not queue the retry again).
//   - These writes cannot tell a stale result from a fresh one: after an
//     Invalidate… query, the dispatcher must drop the results of the
//     jobs that were in flight for that result (CMS
//     WorkerPool.ignore_operation), or a late one is stored and the new
//     job's result is ignored as a duplicate.
//   - Rows that CMS never edits (submission files, tokens, evaluations,
//     user tests and their files) have no Update query.
//   - The query files carry no license header: sqlc would copy a leading
//     comment into the first query. Like every file of the repository
//     they are AGPL-3.0-or-later.
package store

import (
	"context"
	"errors"
	"math/rand/v2"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/d4nd3r/contest-management-system-enchanced/internal/store/q"
)

// Store gives access to the database: Q runs single queries on the pool,
// InTx runs several in a transaction.
type Store struct {
	Pool *pgxpool.Pool
	Q    *q.Queries
}

// New returns a Store on pool.
func New(pool *pgxpool.Pool) *Store {
	return &Store{Pool: pool, Q: q.New(pool)}
}

// TxRetries is how many times a transaction that failed on a
// serialization failure or a deadlock is run again.
const TxRetries = 3

// InTx runs fn in a READ COMMITTED transaction: committed if fn returns
// nil, rolled back otherwise (also on panic). See RunTx for the retries.
func (s *Store) InTx(ctx context.Context, fn func(*q.Queries) error) error {
	return s.RunTx(ctx, pgx.TxOptions{}, func(tx pgx.Tx) error {
		return fn(s.Q.WithTx(tx))
	})
}

// RunTx runs fn in a transaction with the given options, for code that
// needs the pgx.Tx itself (hand-written queries, other isolation
// levels). A transaction that fails on a serialization failure or a
// deadlock is run again from the start, up to TxRetries times after a
// short random pause, so fn must not have effects outside the
// transaction.
func (s *Store) RunTx(ctx context.Context, opts pgx.TxOptions, fn func(pgx.Tx) error) error {
	for attempt := 0; ; attempt++ {
		err := pgx.BeginTxFunc(ctx, s.Pool, opts, fn)
		if err == nil || attempt == TxRetries || !Retryable(err) {
			return err
		}
		// Random pauses spread the competing transactions out; they grow
		// with the attempts (up to 5, 10, 20 ms).
		pause := time.Duration(rand.Int64N(int64(5*time.Millisecond) << attempt))
		select {
		case <-ctx.Done():
			return errors.Join(err, ctx.Err())
		case <-time.After(pause):
		}
	}
}

// Retryable reports whether err is a serialization failure or a deadlock:
// the transaction did nothing and can be run again.
func Retryable(err error) bool {
	var pgErr *pgconn.PgError
	if !errors.As(err, &pgErr) {
		return false
	}
	switch pgErr.Code {
	case "40001", // serialization_failure
		"40P01": // deadlock_detected
		return true
	}
	return false
}

// IsUniqueViolation reports whether err is a violation of the unique
// constraint (or primary key) named constraint; an empty name matches
// any.
func IsUniqueViolation(err error, constraint string) bool {
	var pgErr *pgconn.PgError
	return errors.As(err, &pgErr) && pgErr.Code == "23505" &&
		(constraint == "" || pgErr.ConstraintName == constraint)
}
